{
  "name": "workstation",
  "description": "managed-by: personal-multi-harness-workstation-configuration; source: global/allow-list.conf; release: v9.9.9; commit: aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa; do not edit, re-run the installer",
  "tools": [
    "*"
  ],
  "allowedTools": [
    "fs_read"
  ],
  "toolsSettings": {
    "execute_bash": {
      "allowedCommands": [
        "^git status( [^;&|<>$`(){}\\n\\r]*)?$",
        "^git rev-parse( [^;&|<>$`(){}\\n\\r]*)?$",
        "^gh pr view( [^;&|<>$`(){}\\n\\r]*)?$"
      ],
      "autoAllowReadonly": false
    }
  },
  "permissions": {
    "rules": [
      {
        "capability": "shell",
        "match": [
          "git status *",
          "git status",
          "git rev-parse *",
          "git rev-parse",
          "gh pr view *",
          "gh pr view"
        ],
        "exclude": [
          "*;*",
          "*&*",
          "*|*",
          "*<*",
          "*>*",
          "*$*",
          "*`*",
          "*(*",
          "*)*",
          "*{*",
          "*}*",
          "*\n*",
          "*\r*"
        ],
        "effect": "allow"
      },
      {
        "capability": "fs_read",
        "effect": "allow"
      }
    ]
  }
}
